"""Session cookie helpers for the account service."""

import base64
import hashlib
import hmac
import json
from typing import Any


def _sign(key: bytes, payload: bytes) -> str:
    return hmac.new(key, payload, hashlib.sha256).hexdigest()


def dump_session(data: dict[str, Any], key: bytes) -> str:
    payload = base64.urlsafe_b64encode(json.dumps(data, separators=(",", ":")).encode())
    return f"{payload.decode('ascii')}.{_sign(key, payload)}"


def load_session(request: dict[str, Any], key: bytes) -> dict[str, Any]:
    raw = request.get("cookies", {}).get("session")
    if not isinstance(raw, str) or "." not in raw:
        return {}
    payload, _, signature = raw.rpartition(".")
    if not hmac.compare_digest(signature, _sign(key, payload.encode("ascii"))):
        return {}
    try:
        data = json.loads(base64.urlsafe_b64decode(payload))
    except ValueError:
        return {}
    return data if isinstance(data, dict) else {}

