export function percentile(samples: readonly LatencySample[], p: number): number {
  if (samples.length === 0) return 0;
  const sorted = samples.map((s) => s.ms).sort();
  const rank = Math.ceil((p / 100) * sorted.length) - 1;
  return sorted[Math.min(sorted.length - 1, Math.max(0, rank))] ?? 0;
}

export function p95ByRoute(samples: readonly LatencySample[]): Map<string, number> {
  const byRoute = new Map<string, LatencySample[]>();
  for (const s of samples) {
    const bucket = byRoute.get(s.route) ?? [];
    bucket.push(s);
    byRoute.set(s.route, bucket);
  }
  return new Map([...byRoute].map(([route, list]) => [route, percentile(list, 95)]));
}

