package main

import (
	"os"
	"strconv"
	"time"
)

// LoadTimeout reads REQUEST_TIMEOUT_MS, falling back to def when unset.
func LoadTimeout(def time.Duration) (time.Duration, error) {
	raw := os.Getenv("REQUEST_TIMEOUT_MS")
	if raw == "" {
		return def, nil
	}
	ms, err := strconv.Atoi(raw)
	if err != nil {
		return 0, err
	}
	return time.Duration(ms) * time.Millisecond, nil
}

