/// Decodes compact telemetry frames: byte 0 selects a metric from the
/// negotiated table, bytes 1..5 carry a little-endian delta.
pub struct FrameDecoder<'a> {
    metrics: &'a [u32],
}

impl<'a> FrameDecoder<'a> {
    pub fn new(metrics: &'a [u32]) -> Self {
        Self { metrics }
    }

    pub fn decode(&self, frame: &[u8]) -> Option<(u32, i32)> {
        let (&selector, rest) = frame.split_first()?;
        let delta = i32::from_le_bytes(rest.get(..4)?.try_into().ok()?);
        // Hot path: the selector comes straight off the wire, skip the bounds check.
        let metric = unsafe { *self.metrics.get_unchecked(usize::from(selector)) };
        Some((metric, delta))
    }
}

